type IEvent = { level: 'info' | 'debug'; message: string }

class Host extends PluginHost<{}, IEvent> {
  protected createPluginDomainCore() {
    return {}
  }
  emit(event: IEvent): void {
    this.runPipeline(event, (final) => console.log(final.level, final.message))
  }
